/**
 * How hard a drive is, chosen on the home screen (remembered on this device): how busy the roads are, how long a
 * mock test lasts, and how much the instructor reminds you on a lesson.
 */
export type Difficulty='easy'|'standard'|'test';

export interface DifficultyLevel{
  id:Difficulty;
  label:string;
  summary:string;
  /** Background cars and buses on the roads. */
  traffic:{cars:number;buses:number};
  /** Mock test route length (metres) and the most time it may take (seconds). */
  mockMetres:number;
  mockSeconds:number;
  /** Lessons: the instructor's reminders before each junction (otherwise only the word after it). */
  reminders:boolean;
}

export const DIFFICULTIES:Record<Difficulty,DifficultyLevel>={
  easy:{id:'easy',label:'Easy',summary:'Quiet roads. Mock test about 10 minutes. Lessons with reminders.',
    traffic:{cars:6,buses:1},mockMetres:3000,mockSeconds:900,reminders:true},
  standard:{id:'standard',label:'Standard',summary:'Normal traffic. Mock test about 20 minutes. Lessons with reminders.',
    traffic:{cars:12,buses:2},mockMetres:6000,mockSeconds:1800,reminders:true},
  test:{id:'test',label:'Test day',summary:'Busy roads. Mock test about 40 minutes, like the real test. Lessons without reminders.',
    traffic:{cars:20,buses:3},mockMetres:11000,mockSeconds:3000,reminders:false}
};

const KEY='dp-difficulty';
export function savedDifficulty():Difficulty{
  try{const v=localStorage.getItem(KEY);if(v==='easy'||v==='standard'||v==='test')return v}catch{/* private mode */}
  return 'standard';
}
export function saveDifficulty(d:Difficulty):void{try{localStorage.setItem(KEY,d)}catch{/* private mode */}}
